def balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)                 # remember every opener
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False                 # closer with no matching opener
    return not stack                         # anything left open is unbalanced

for s in ["(a[b]{c})", "(a[b)]", "((x)", "print(f(x[0]))"]:
    print(f"{s:<16} {balanced(s)}")

def two_sum(numbers, target):
    seen = {}                                # value -> index where we saw it
    for i, n in enumerate(numbers):
        if target - n in seen:
            return seen[target - n], i
        seen[n] = i
    return None

prices = [12, 7, 30, 18, 5, 21]
print("two prices adding to 23 are at positions", two_sum(prices, 23))
print("two prices adding to 100:", two_sum(prices, 100))

def binary_search(sorted_items, target):
    low, high, checks = 0, len(sorted_items) - 1, 0
    while low <= high:
        checks += 1
        mid = (low + high) // 2
        if sorted_items[mid] == target:
            return mid, checks
        if sorted_items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return None, checks

roll_numbers = list(range(1000, 101000, 3))     # 33,334 sorted roll numbers
print(len(roll_numbers), "items")
print("find 70003:", binary_search(roll_numbers, 70003))
print("find 70004 (not there):", binary_search(roll_numbers, 70004))
